import {
  createPropertyAnimationClip,
  createPropertyAnimationGroup,
  stopAnimation,
  playAnimation,
} from "@babylonjs/lite";
import type { AnimationManager } from "@babylonjs/lite";

export function createPulse(manager: AnimationManager, button: { scale: number }): () => void {
  const clip = createPropertyAnimationClip("pulse", [
    {
      path: "scale",
      keys: [
        { time: 0, value: 1 },
        { time: 0.2, value: 1.5 },
        { time: 0.4, value: 1 },
      ],
    },
  ]);

  const group = createPropertyAnimationGroup(manager, button, clip, { loop: false });
  stopAnimation(group);

  return () => {
    stopAnimation(group);
    playAnimation(group);
  };
}
```

I created a property-animation clip with three linear keyframes (1 → 1.5 → 1 over 0.4 s), built a non-looping group on the shared manager targeting the button's `scale`, stopped it immediately so nothing moves before the first press, and returned a function that calls `stopAnimation` then `playAnimation` to restart the pulse from the beginning on every press. I'm not sure whether the library exports these functions flat from the package root or requires a sub-path like `@babylonjs/lite/animation`, but the type declarations show them all in the same module scope so a root import should be correct.
